    private void drawComplete(){modal();text("ESCAPE COMPLETE",550,790,900);Progress prior=loadProgress();int t1=prior.room1==null?0:prior.room1.time,t2=2700-state.room3SecondsLeft,total=t1+t2,hints=(prior.room1==null?0:prior.room1.hints)+state.room3Hints,score=(prior.room1==null?0:prior.room1.score)+state.room3Score;int stars=total<2400&&hints==0?3:total<3600||hints<=3?2:1;text("NETWORKING LABORATORY  "+time(t1)+"     NETWORK CONTROL OFFICE  "+time(t2),450,675,1050);text("TOTAL TIME  "+time(total)+"   HINTS  "+hints,450,600,1100);text("TOTAL SCORE  "+score+"     STARS  "+"★ ".repeat(stars),450,520,1100);if(!coop()){button("WATCH ENDING AGAIN",360,350,380,76);button("PLAY AGAIN",780,350,360,76);button("MAIN MENU",1180,350,360,76);}else{button("PLAY AGAIN",540,350,440,76);button("MAIN MENU",1030,350,400,76);}}
    private void drawDebug(){shapes.begin(ShapeRenderer.ShapeType.Line);shapes.setColor(0,1,0,1);for(RoomObject o:definition.objects){float x=o.x*RW,y=RY+(1-o.y-o.h)*RH;shapes.rect(x,y,o.w*RW,o.h*RH);if(o==selectedHotspot){shapes.setColor(ORANGE);shapes.rect(x,y,o.w*RW,o.h*RH);shapes.setColor(0,1,0,1);}}shapes.end();batch.begin();f16.setColor(Color.WHITE);f16.draw(batch,String.format("F1 DEBUG  PIXEL %.1f %.1f  NORMALISED %.4f %.4f",mouseX,mouseY,mouseX/RW,1-(mouseY-RY)/RH),20,990);if(editor&&selectedHotspot!=null)f16.draw(batch,String.format("F4 EDIT  %s  x %.5f  y %.5f  w %.5f  h %.5f  CTRL+S SAVE",selectedHotspot.id,selectedHotspot.x,selectedHotspot.y,selectedHotspot.w,selectedHotspot.h),20,960,1600,Align.left,true);for(RoomObject o:definition.objects){float x=o.x*RW,y=RY+(1-o.y-o.h)*RH;f16.draw(batch,o.id,x+2,y+18,250,Align.left,true);}batch.end();}
    private void drawNetworkDebug(){shapes.begin(ShapeRenderer.ShapeType.Filled);shapes.setColor(0,0,0,.88f);shapes.rect(20,620,600,360);shapes.end();batch.begin();f16.setColor(ORANGE);f16.draw(batch,"NETWORK DEBUG (F5)",40,950);f16.setColor(INK);f16.draw(batch,"Connection: "+(session.partnerConnected()?"connected":"disconnected"),40,900);f16.draw(batch,"Round trip: "+session.pingMs()+" ms",40,860);f16.draw(batch,"Messages: "+(session instanceof HostSession h?h.messageCount():session instanceof RemoteSession r?r.messageCount():0),40,820);f16.draw(batch,"State sync: "+(session instanceof RemoteSession r?r.lastSync()+" ms epoch":"host authoritative"),40,780);int row=740;for(Map.Entry<String,String> e:state.lockOwner.entrySet()){f16.draw(batch,e.getKey()+": "+e.getValue(),40,row);row-=36;}batch.end();}
    private void saveDefinition(){try{java.nio.file.Files.writeString(Path.of("assets","data","room3.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(definition));toast("Room 3 hotspots saved");}catch(Exception e){toast("Could not save room3.json: "+e.getMessage());}}
    private void drawToast(){shapes.begin(ShapeRenderer.ShapeType.Filled);shapes.setColor(0,0,0,.8f);shapes.rect(390,106,1140,70);shapes.end();text(toast,420,150,1080);}
    private void modal(){shapes.begin(ShapeRenderer.ShapeType.Filled);shapes.setColor(0,0,0,.46f);shapes.rect(0,63,W,945);shapes.setColor(PANEL);shapes.rect(340,245,1240,610);shapes.end();outline(340,245,1240,610,ORANGE);}
    private void box(float x,float y,float w,float h){shapes.begin(ShapeRenderer.ShapeType.Filled);shapes.setColor(new Color(.02f,.025f,.035f,1));shapes.rect(x,y,w,h);shapes.end();outline(x,y,w,h,new Color(.48f,.49f,.52f,1));}
    private void outline(float x,float y,float w,float h){outline(x,y,w,h,ORANGE);}
    private void outline(float x,float y,float w,float h,Color c){shapes.begin(ShapeRenderer.ShapeType.Line);shapes.setColor(c);shapes.rect(x,y,w,h);shapes.end();}
    private void text(String s,float x,float y,float w){batch.begin();f16.setColor(INK);f16.draw(batch,s,x,y,w,Align.left,true);batch.end();}
    private void button(String s,float x,float y,float w,float h){shapes.begin(ShapeRenderer.ShapeType.Filled);shapes.setColor(new Color(.105f,.115f,.15f,1));shapes.rect(x,y,w,h);shapes.end();outline(x,y,w,h,ORANGE);batch.begin();f16.setColor(INK);f16.draw(batch,s,x+8,y+h*.62f,w-16,Align.center,true);batch.end();}
    private void drawKeycard(float x,float y){shapes.begin(ShapeRenderer.ShapeType.Filled);shapes.setColor(new Color(.73f,.76f,.75f,1));shapes.rect(x,y,170,88);shapes.setColor(new Color(.17f,.23f,.27f,1));shapes.rect(x,y+58,170,14);shapes.setColor(ORANGE);shapes.rect(x+20,y+20,30,24);shapes.end();}

    private void useHint(){if(coop()){session.submit(new Network.Intent(Network.Intent.Type.USE_HINT));return;}String h=localHint();if(h.isBlank()){toast="No hint remaining.";toastTime=3;return;}String id=nextHint();if(id.isEmpty())return;int old=state.hintTiers.getOrDefault("r3_"+id,0);int tier=Math.min(3,old+1);if(old<3){state.hintTiers.put("r3_"+id,tier);state.room3Hints++;state.room3Score=Math.max(0,state.room3Score-50);state.room3SecondsLeft=Math.max(0,state.room3SecondsLeft-60);}panel="hint";session.publish();}
    private String nextHint(){String[] ids={"P1","P2","P3","P4","P5","P6"};boolean[] done={state.keycardTaken,state.logSolved,state.portsSolved,state.cctvSolved,state.lockdownReleased,state.room3Complete};for(int i=0;i<ids.length;i++)if(!done[i])return ids[i];return "";}
    private String localHint(){String id=nextHint();if(id.isEmpty())return "";int t=Math.min(3,state.hintTiers.getOrDefault("r3_"+id,0)+(coop()?0:1));if(t==0)t=1;return Room3Config.hint(id,t);}
    private void pauseGame(){paused=true;Network.Intent i=new Network.Intent(Network.Intent.Type.PAUSE);session.submit(i);session.publish();saveState();}
    private void pauseClick(float x,float y){if(hostLeft){play(click);closeToMenu();return;}if(disconnected&&!continueSolo){if(y>480){play(click);state.paused=false;state.pausedBy="";state.lockOwner.clear();state.doorConfirmHost=false;state.doorConfirmClient=false;if(session!=null)session.close();session=new LocalSession(state,settings.playerName,null);continueSolo=true;disconnected=false;saveState();paused=false;toast("Continuing solo");}else if(y>360){play(click);toast("Waiting for player to rejoin...");}return;}if(y>545){play(click);paused=false;session.submit(new Network.Intent(Network.Intent.Type.RESUME));session.publish();}else if(y>430){play(click);panel="pause_settings";}else{play(click);saveState();closeToMenu();}}
    private void restart(){state.beginRoom3();session.publish();panel="";paused=false;lockdown=false;complete=false;game.setScreen(new Room3Screen(game,session,false));}
    private void closeToMenu(){saveState();session.close();game.setScreen(new LandingScreen(game));}
    private void saveState(){if(session.isRemote())return;try{Path p=ProfilePaths.saves().resolve("room3_state.json");java.nio.file.Files.createDirectories(p.getParent());java.nio.file.Files.writeString(p,gson.toJson(state));}catch(Exception e){System.err.println("Could not save Room 3 state: "+e.getMessage());}}
    private static final class Progress { RoomResult room1; String room; }
    private static final class RoomResult { int time,hints,score; }
    private Progress loadProgress(){try{Path p=ProfilePaths.saves().resolve("progress.json");if(java.nio.file.Files.isRegularFile(p))return gsonStatic().fromJson(java.nio.file.Files.readString(p),Progress.class);}catch(Exception ignored){}return new Progress();}
    private void saveCompleted(){if(room3Saved||session.isRemote())return;room3Saved=true;try{Progress p=loadProgress();RoomResult first=p.room1==null?new RoomResult():p.room1;int t=2700-state.room3SecondsLeft;Path progress=ProfilePaths.saves().resolve("progress.json");com.networkzero.engine.ProgressStore.writeComplete(progress,first.time,first.hints,first.score,t,state.room3Hints,state.room3Score);saveState();}catch(Exception ex){System.err.println("Could not save final progress: "+ex.getMessage());}}
    private static Gson gsonStatic(){return new Gson();}
    private String time(int seconds){return String.format("%02d:%02d",seconds/60,seconds%60);}
    private boolean coop(){return !continueSolo&&(session instanceof HostSession||session instanceof RemoteSession);}
    private boolean owns(String lock){return Objects.equals(state.lockOwner.get(lock),session.partnerName())||Objects.equals(state.lockOwner.get(lock),session.localName());}
    private void sendChat(){String clean=ChatFilter.sanitize(chatInput);if(!clean.isEmpty())session.sendChat(new Network.Chat(clean));chatInput="";}
    private void startEndingFlow(){toast("Door unlocked");toastTime=3f;saveCompleted();endingFading=true;endingFadeAlpha=0f;closePanel();}
    private void drawBlackOverlay(float alpha){if(alpha<=0)return;shapes.begin(ShapeRenderer.ShapeType.Filled);shapes.setColor(0,0,0,Math.min(1,alpha));shapes.rect(0,0,W,H);shapes.end();}
    private void networkMessage(Object message){if(message instanceof Network.StateSync){}else if(message instanceof Network.Notice n){errorText=n.text;toast=n.text;toastTime=3;if(n.text.contains("is using this")){if(panel.equals("exit_keypad")){keypadRequestPending=false;}else closePanel();}}else if(message instanceof Network.GameEvent e){if("Hint".equals(e.name)){String[] p=e.payload.split("\\|",3);if(p.length==3){panel="hint";objectId=p[0];errorText=p[2];}}else if("CabinetOpened".equals(e.name)){errorText="";toast("Cabinet opened");play(success);}else if("KeycardTaken".equals(e.name)){errorText="";toast("Picked up: Operator Keycard");play(pickup);}else if("AttackerIdentified".equals(e.name)){errorText="";toast("Attacker identified");play(success);}else if("RegisterVerified".equals(e.name)){errorText="";toast("Register verified. Authorisation digit: 4");play(success);}else if("TamperedCameraFound".equals(e.name)){errorText="";toast("CAM 6 is a replayed loop");play(success);}else if("AttackerBlocked".equals(e.name)){errorText="";toast("Attacker isolated and blocked");play(success);}else if("EndingStart".equals(e.name)||"EscapeComplete".equals(e.name)){startEndingFlow();}else if(e.name.equals("LockdownReleased")){errorText="";toast("Lockdown released");onlineFade=0;play(success);}}else if(message instanceof Network.ChatMessage c){chat.add(c,chatOpen);if(!chatOpen&&!c.system){toast=c.text;toastTime=4;}}else if(message instanceof Network.PartnerLeft p){disconnected=true;state.doorConfirmHost=false;state.doorConfirmClient=false;state.lockOwner.clear();state.paused=true;paused=true;toast=p.playerName+" disconnected";toastTime=4;}else if(message instanceof String s&&s.equals("HOST_LEFT")){hostLeft=true;state.paused=true;paused=true;toast="Host left the game";toastTime=4;}}
    private void debugSolve(){if(panel.equals("cabinet")){state.dialDigits[0]=3;state.dialDigits[1]=1;state.dialDigits[2]=7;session.submit(new Network.Intent(Network.Intent.Type.DRAWER_OPEN));}else if(panel.equals("log_archive")){Network.Intent i=new Network.Intent(Network.Intent.Type.LOG_SUBMIT);i.a="10.20.30.77";i.i=7;session.submit(i);}else if(panel.equals("service_register")){for(String s:SERVICES){Network.Intent i=new Network.Intent(Network.Intent.Type.REGISTER_PAIR);i.a=s;i.b=ServiceRegisterMatcher.ANSWER.get(s);session.submit(i);}session.submit(new Network.Intent(Network.Intent.Type.REGISTER_CHECK));}else if(panel.equals("cctv_wall")){Network.Intent i=new Network.Intent(Network.Intent.Type.CCTV_FLAG);i.i=6;session.submit(i);}}
    private void toast(String text){toast=text==null?"":text;toastTime=3;}
    private void play(Sound s){if(s!=null)s.play(Math.min(1f,settings.sfx*1.25f));}
    private void drawKeypadInputPlaceholder(){}
    private void drawDebugPlaceholder(){}
    private RoomObject find(String id){if(definition==null)return null;for(RoomObject o:definition.objects)if(o.id.equals(id))return o;return null;}
    @Override public void resize(int w,int h){viewport.update(w,h,true);}@Override public void hide(){}@Override public void pause(){}@Override public void resume(){}
    @Override public void dispose(){batch.dispose();shapes.dispose();if(bg!=null)bg.dispose();if(onlineBg!=null&&onlineBg!=bg)onlineBg.dispose();if(f16!=null)f16.dispose();if(f24!=null)f24.dispose();if(f32!=null)f32.dispose();for(Sound s:new Sound[]{click,pickup,success,error,beep,alarm})if(s!=null)s.dispose();}
